import data.glitch_lib

password_keywords := {"password", "pwd", "passphrase", "secret", "admin_password", "master_password", "initial_password"}

check_empty_password(value) {
    value.ir_type == "String"
    value.value == ""
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "String"
    regex.match("^\\s*$", value.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    some keyword in password_keywords
    regex.match(sprintf("(?i).*%s.*", [keyword]), attr.name)

    check_empty_password(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - A password field is present but its value is empty or null. (CWE-258)"
    }
}

