package glitch

import data.glitch_lib

empty_value := {"", null}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    all_attrs := glitch_lib.all_attributes(parent)
    attr := all_attrs[_]

    password_like := {"password", "pwd", "passphrase", "secret", "admin_password", "master_password", "initial_password"}
    regex.match(sprintf("(?i)(%s)", [concat("|", password_like)]), attr.name)

    attr.value.ir_type == "String"
    empty_value[_] == attr.value.value

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - A password field is set to an empty value. (CWE-258)"
    }
}

